import{_ as o,o as t,c as s,ag as a}from"./chunks/framework.CZxGLIO_.js";const p=JSON.parse('{"title":"Troubleshooting","description":"Diagnose Rooster addresses, environments, task states, Cron, logs and restore failures.","frontmatter":{"title":"Troubleshooting","description":"Diagnose Rooster addresses, environments, task states, Cron, logs and restore failures."},"headers":[],"relativePath":"en/docs/rooster/troubleshooting/index.md","filePath":"en/docs/rooster/troubleshooting/index.md"}'),r={name:"en/docs/rooster/troubleshooting/index.md"};function n(i,e,d,c,l,h){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Record the commit, launch method, actual listening address, data directory, task ID and execution ID. Names are not unique; API and agent operations should use IDs.</p><h2 id="port-9090-does-not-respond-or-tasks-are-missing" tabindex="-1">Port 9090 does not respond or tasks are missing <a class="header-anchor" href="#port-9090-does-not-respond-or-tasks-are-missing" aria-label="Permalink to &quot;Port 9090 does not respond or tasks are missing&quot;">​</a></h2><p>Read the <code>rooster ready</code> log first. If 9090 is occupied, Rooster tries the next 100 ports. The browser and agent must use the actual address. Check <code>/api/health</code> on that port with curl.</p><p>If the console works but is empty, check the OS user, <code>ROOSTER_DATA_DIR</code> and launch method. Keep development and everyday instances separate rather than recreating tasks to hide a directory mismatch.</p><h2 id="a-command-works-in-a-terminal-but-is-not-found-by-rooster" tabindex="-1">A command works in a terminal but is not found by Rooster <a class="header-anchor" href="#a-command-works-in-a-terminal-but-is-not-found-by-rooster" aria-label="Permalink to &quot;A command works in a terminal but is not found by Rooster&quot;">​</a></h2><p>Check the working directory, absolute executable path, argument separation, command mode and PATH. Rooster inherits a cached login environment; tray startup may differ from your current terminal. Specify task environment overrides and absolute paths where necessary.</p><p><code>exec</code> does not interpret pipes or redirection. Use <code>shell</code> for <code>|</code>, <code>&gt;</code> or shell variable expansion, checking syntax for the chosen shell.</p><h2 id="a-resident-task-keeps-restarting-and-becomes-disabled" tabindex="-1">A resident task keeps restarting and becomes disabled <a class="header-anchor" href="#a-resident-task-keeps-restarting-and-becomes-disabled" aria-label="Permalink to &quot;A resident task keeps restarting and becomes disabled&quot;">​</a></h2><p>Inspect exit codes, runtime, errors and logs. A run shorter than the default ten seconds counts as a supervisor failure. The default limit is three consecutive failures. <code>maxRetries=0</code> uses the default, not unlimited retries.</p><p>If the command should finish quickly, use a scheduled task. If a service fails to start, verify it manually before enabling supervision. Increasing retries does not fix the underlying launch failure.</p><h2 id="cron-is-missed-or-runs-overlap" tabindex="-1">Cron is missed or runs overlap <a class="header-anchor" href="#cron-is-missed-or-runs-overlap" aria-label="Permalink to &quot;Cron is missed or runs overlap&quot;">​</a></h2><p>Check that the task is enabled, the expression has five fields, the process timezone is correct and the next five trigger times match expectations. Use <code>CRON_TZ=Asia/Shanghai</code> when an explicit timezone is needed.</p><p><code>skip</code> blocks overlapping execution, while <code>parallel</code> permits several active runs. Runtime state can describe only one active execution, so inspect history for all of them. Instance limits can also reject new runs.</p><h2 id="a-disabled-task-is-still-running" tabindex="-1">A disabled task is still running <a class="header-anchor" href="#a-disabled-task-is-still-running" aria-label="Permalink to &quot;A disabled task is still running&quot;">​</a></h2><p>Disabling a scheduled task cancels future triggers, not an existing execution. Stop the execution ID separately. Manually started resident executions can also require an explicit stop. Stopping is asynchronous: wait for a terminal state before editing or deleting.</p><p>For read-only configuration or <code>422</code> on edits, confirm the task is disabled and has no active executions. PUT fully replaces configuration and cannot change <code>kind</code>.</p><h2 id="a-successful-api-response-is-followed-by-task-failure" tabindex="-1">A successful API response is followed by task failure <a class="header-anchor" href="#a-successful-api-response-is-followed-by-task-failure" aria-label="Permalink to &quot;A successful API response is followed by task failure&quot;">​</a></h2><p><code>202</code> means accepted, not successfully completed. Find the returned execution ID in history and inspect <code>status</code>, <code>exitCode</code> and <code>error</code>. A timeout can report <code>context deadline exceeded</code>.</p><p>After a connection loss during create or run, inspect state before retrying. There is no idempotency key, and blind retries can duplicate work.</p><h2 id="missing-logs-or-growing-disk-usage" tabindex="-1">Missing logs or growing disk usage <a class="header-anchor" href="#missing-logs-or-growing-disk-usage" aria-label="Permalink to &quot;Missing logs or growing disk usage&quot;">​</a></h2><p>The log endpoint shows only the last 64 KiB of the current file. Earlier output may be in archives. A new execution may not have created its log yet, and restored snapshots do not restore log files.</p><p>The 20 MB threshold and three backups apply per log, not globally. Preview retention using <a href="./../maintenance/">backup and logs</a>, then inspect errors when applying cleanup.</p><h2 id="restore-rejects-the-destination" tabindex="-1">Restore rejects the destination <a class="header-anchor" href="#restore-rejects-the-destination" aria-label="Permalink to &quot;Restore rejects the destination&quot;">​</a></h2><p>Restore requires a new directory and never overwrites an existing instance. The source should be the standalone snapshot downloaded from <code>/api/backup</code>; a copy with a nonempty WAL is rejected. Follow the <a href="./../maintenance/">recovery procedure</a>.</p><p>Report sanitized configuration, errors, task/execution IDs and reproduction steps at <a href="https://github.com/leancodebox/rooster/issues" target="_blank" rel="noreferrer">Rooster Issues</a>. Remove secrets from environment values.</p><hr><p>Sources checked on 2026-11-15：<a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/README.md" target="_blank" rel="noreferrer">Runtime guide</a> · <a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/internal/httpapi/agent/references/api.md" target="_blank" rel="noreferrer">API behavior</a> · <a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/internal/roosterapp/restore.go" target="_blank" rel="noreferrer">Restore implementation</a>。</p>',28)])])}const b=o(r,[["render",n]]);export{p as __pageData,b as default};
